<script setup lang="ts">
/**
 * ScholarStack logo as inline SVG, coloured by the theme.
 *
 * Inline on purpose: an SVG loaded via ``<img>`` is a separate document, so
 * the page's CSS variables never reach it and the logo would stay red. Here
 * the S and "Stack" derive from ``--color-primary`` (the accent, lifted to a
 * readable lightness in dark mode) and "Scholar" uses the text colour, so the
 * logo follows the accent and light/dark mode without a file per mode.
 *
 * The S is shaded: each gradient stop of the source artwork
 * (``assets/ScholarStackLogo.svg``) is the accent mixed with black or white
 * in the same proportion as the original red, so the shading survives any
 * accent colour.
 *
 * ``mark`` shows only the S, cropped to it (collapsed sidebar).
 */
import { useId } from 'vue'

defineProps<{ mark?: boolean }>()

// One id prefix per instance: the logo can appear twice on a page (sidebar
// and dashboard), and duplicate gradient/clip ids would be invalid markup.
const prefix = `ss-logo-${useId()}`
const idFor = (name: string) => `${prefix}-${name}`
</script>

